#include "safety_platform.h"
#include "sine_control.h"

static unsigned int fault_read_calls;

static x_nucleo_ihm16m1_status_t fault_asserted_callback(bool *fault, int cmock_num_calls)
{
    (void)cmock_num_calls;
    *fault = true;
    return X_NUCLEO_IHM16M1_OK;
}

static x_nucleo_ihm16m1_status_t fault_asserted_then_cleared_callback(
    bool *fault,
    int cmock_num_calls)
{
    (void)cmock_num_calls;
    fault_read_calls++;
    *fault = (fault_read_calls == 1U);
    return X_NUCLEO_IHM16M1_OK;
}

void setUp(void)
{
    fault_read_calls = 0U;
    (void)safety_platform_init();
}

